# HYPA against the original implementation (tlarock/hypa + pathpy 2.2.0).
# Fixtures were generated by running the original Python code on small,
# adversarial corpora (see local_testing_and_equivalence/hypa_oracles).
# Python rounds Xi inside every fitting sweep; Nestimate fits continuously.
# Where the rounded fit already preserves strengths the two agree to machine
# precision; in the three fixtures where it does not, Nestimate is checked
# against the strength-preservation invariant instead and labels must agree.

skip_on_cran()

.oracle_fixtures <- readRDS(test_path("fixtures", "hypa_oracles.rds"))
.rounded_fit_off <- c("fit_nonconverged", "fit_rollback", "self_loops_and_ends")

.oracle_compare <- function(fx, p_adjust) {
  h <- build_hypa(fx$trajectories, order = fx$order, alpha = fx$alpha,
                  min_count = fx$min_count, p_adjust = p_adjust)
  ours <- h$scores[c("order", "path", "observed", "expected", "p_under",
                     "p_over", "anomaly")]
  merged <- merge(ours, fx$rows, by = c("order", "path"), all = TRUE,
                  suffixes = c("", "_py"))
  list(h = h, merged = merged)
}

lapply(.oracle_fixtures, function(fx) {
  test_that(sprintf("HYPA matches the original Python oracle: %s", fx$name), {
    none <- .oracle_compare(fx, "none")
    bh <- .oracle_compare(fx, "BH")
    m <- none$merged
    # Same scored path set, same counts.
    expect_false(anyNA(m$observed))
    expect_false(anyNA(m$observed_py))
    expect_identical(m$observed, m$observed_py)
    # Same classification, uncorrected and BH.
    expect_identical(m$anomaly, m$anomaly_none)
    expect_identical(bh$merged$anomaly, bh$merged$anomaly_BH)
    # Strict over tail is the complement of the lower tail.
    expect_equal(m$p_over, 1 - m$p_under, tolerance = 1e-12)
    if (fx$name %in% .rounded_fit_off) {
      # Expected counts preserve every De Bruijn node's strength.
      lapply(none$h$by_order, function(layer) {
        e <- sum(layer$adjacency) * layer$xi / sum(layer$xi)
        expect_lt(max(abs(rowSums(e) - rowSums(layer$adjacency))), 1e-8)
        expect_lt(max(abs(colSums(e) - colSums(layer$adjacency))), 1e-8)
      })
    } else {
      expect_equal(m$expected, m$expected_py, tolerance = 1e-12)
      expect_equal(m$p_under, m$p_under_py, tolerance = 1e-12)
    }
  })
})

test_that("absent paths with enough expected mass are under-represented", {
  fx <- .oracle_fixtures$absent_possible
  m <- .oracle_compare(fx, "none")$merged
  absent <- m[m$observed == 0L, , drop = FALSE]
  expect_gt(nrow(absent), 0L)
  expect_true(all(absent$expected >= fx$min_count))
  expect_true(all(absent$anomaly == "under"))
})
